export function BrandLogo({ height }: { height: number }) {
  const { scheme } = useTheme();
  return (
    <Svg
      width={(height * 1741) / 368}
      height={height}
      viewBox="0 0 1741 368"
      accessibilityRole="image"
      accessibilityLabel="Habitual Fit"
    >
      <Path
        d={SIMBOLO}
        fill="#01D798"
        fillRule="evenodd"
        transform="translate(-6 -6) scale(0.25)"
      />
      <G transform="translate(481 4) scale(1.22) translate(-481 -35)">
        <Path
          d={HABITUAL}
          fill={scheme === "dark" ? "#FFFFFF" : "#020306"}
          fillRule="evenodd"
          transform="translate(481.172 33.45) scale(0.293)"
        />
        <Path
          d={FIT}
          fill="#01D798"
          fillRule="evenodd"
          transform="translate(472.97 247.852) scale(0.293)"
        />
      </G>
    </Svg>
  );
}
